import{_ as t,o as a,c as o,ae as s}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"PDF Rescue (OCR)","description":"","frontmatter":{},"headers":[],"relativePath":"tools/pdf-rescue.md","filePath":"tools/pdf-rescue.md"}'),i={name:"tools/pdf-rescue.md"};function r(l,e,n,d,p,c){return a(),o("div",null,e[0]||(e[0]=[s(`<h1 id="pdf-rescue-ocr" tabindex="-1">PDF Rescue (OCR) <a class="header-anchor" href="#pdf-rescue-ocr" aria-label="Permalink to &quot;PDF Rescue (OCR)&quot;">​</a></h1><p>This page is the GitBook version of the original PDF Rescue guide.</p><p>If you prefer the repository copy, see: <a href="https://github.com/michaelbeijer/Supervertaler/blob/main/docs/guides/PDF_RESCUE.md" target="_blank" rel="noreferrer">https://github.com/michaelbeijer/Supervertaler/blob/main/docs/guides/PDF_RESCUE.md</a></p><hr><h1 id="pdf-rescue-ai-powered-ocr-tool" tabindex="-1">PDF Rescue - AI-Powered OCR Tool <a class="header-anchor" href="#pdf-rescue-ai-powered-ocr-tool" aria-label="Permalink to &quot;PDF Rescue - AI-Powered OCR Tool&quot;">​</a></h1><p><strong>Part of <a href="https://supervertaler.com/" target="_blank" rel="noreferrer">Supervertaler</a> • by Michael Beijer</strong></p><hr><h2 id="📖-overview" tabindex="-1">📖 Overview <a class="header-anchor" href="#📖-overview" aria-label="Permalink to &quot;📖 Overview&quot;">​</a></h2><p><strong>PDF Rescue</strong> is a specialised AI-powered OCR tool designed to extract clean, editable text from poorly formatted PDFs. Built into Supervertaler, it uses vision-capable LLM OCR to intelligently recognise text, formatting, redactions, stamps, and signatures—producing professional, translator-ready documents.</p><h3 id="🎯-the-problem-it-solves" tabindex="-1">🎯 The Problem It Solves <a class="header-anchor" href="#🎯-the-problem-it-solves" aria-label="Permalink to &quot;🎯 The Problem It Solves&quot;">​</a></h3><p>Have you ever received a PDF translation job where:</p><ul><li>The text won&#39;t copy-paste cleanly?</li><li>Line breaks are all over the place?</li><li>Formatting is completely broken?</li><li>Traditional OCR produces gibberish?</li><li>Redacted sections show as black boxes?</li><li>Stamps and signatures clutter the text?</li></ul><p><strong>PDF Rescue fixes all of this.</strong></p><h3 id="real-world-success-story" tabindex="-1">Real-World Success Story <a class="header-anchor" href="#real-world-success-story" aria-label="Permalink to &quot;Real-World Success Story&quot;">​</a></h3><blockquote><p><em>&quot;I had a client reach out for a rush job—a 4-page legal document that had clearly been scanned badly. Traditional OCR couldn&#39;t handle it, and manual retyping would have taken hours.</em></p><p><em>I used PDF Rescue&#39;s one-click PDF import, processed all 4 pages with AI OCR, and it produced a flawless Word document that I could immediately start working with. What would have been a multi-day nightmare became a straightforward job I could deliver on time.</em></p><p><em>I was able to tell my client that I could handle the job—and delivered professional quality. PDF Rescue literally saved a client relationship.&quot;</em></p><p>— Michael Beijer, Professional Translator</p></blockquote><hr><h2 id="✨-key-features" tabindex="-1">✨ Key Features <a class="header-anchor" href="#✨-key-features" aria-label="Permalink to &quot;✨ Key Features&quot;">​</a></h2><h3 id="_1-📄-one-click-pdf-import" tabindex="-1">1. 📄 <strong>One-Click PDF Import</strong> <a class="header-anchor" href="#_1-📄-one-click-pdf-import" aria-label="Permalink to &quot;1. 📄 **One-Click PDF Import**&quot;">​</a></h3><ul><li><strong>No external tools needed</strong> - Import PDFs directly</li><li><strong>Automatic page extraction</strong> - Each page saved as high-quality PNG (2x resolution)</li><li><strong>Persistent storage</strong> - Images saved next to source PDF in <code>{filename}_images/</code> folder</li><li><strong>Client-ready</strong> - Images can be delivered to end clients if needed</li></ul><h3 id="_2-🧠-smart-ai-powered-ocr" tabindex="-1">2. 🧠 <strong>Smart AI-Powered OCR</strong> <a class="header-anchor" href="#_2-🧠-smart-ai-powered-ocr" aria-label="Permalink to &quot;2. 🧠 **Smart AI-Powered OCR**&quot;">​</a></h3><ul><li><strong>Vision-capable LLM OCR</strong> - High accuracy OCR</li><li><strong>Context-aware</strong> - Understands document structure and formatting</li><li><strong>Intelligent cleanup</strong> - Fixes line breaks, spacing, and formatting issues</li><li><strong>Redaction handling</strong> - Inserts descriptive placeholders like <code>[naam]</code>, <code>[bedrag]</code> in document language</li><li><strong>Stamps &amp; signatures</strong> - Detects and describes non-text elements: <code>[stempel]</code>, <code>[handtekening]</code></li></ul><h3 id="_3-🎨-optional-formatting-preservation" tabindex="-1">3. 🎨 <strong>Optional Formatting Preservation</strong> <a class="header-anchor" href="#_3-🎨-optional-formatting-preservation" aria-label="Permalink to &quot;3. 🎨 **Optional Formatting Preservation**&quot;">​</a></h3><ul><li><strong>Markdown-based</strong> - Uses <code>**bold**</code>, <code>*italic*</code>, <code>__underline__</code></li><li><strong>Toggle on/off</strong> - User-controlled via checkbox</li><li><strong>Clean output</strong> - Markdown converted to proper formatting in DOCX export</li><li><strong>Visual preview</strong> - See formatting markers before export</li></ul><h3 id="_4-📊-batch-processing" tabindex="-1">4. 📊 <strong>Batch Processing</strong> <a class="header-anchor" href="#_4-📊-batch-processing" aria-label="Permalink to &quot;4. 📊 **Batch Processing**&quot;">​</a></h3><ul><li><strong>Process selected</strong> - Work on individual images</li><li><strong>Process all</strong> - Batch process entire document</li><li><strong>Progress tracking</strong> - Visual progress bar and status updates</li><li><strong>Skip processed</strong> - Already-processed images are skipped (unless re-selected)</li></ul><h3 id="_5-📝-comprehensive-logging" tabindex="-1">5. 📝 <strong>Comprehensive Logging</strong> <a class="header-anchor" href="#_5-📝-comprehensive-logging" aria-label="Permalink to &quot;5. 📝 **Comprehensive Logging**&quot;">​</a></h3><ul><li><strong>Activity log integration</strong> - All operations logged with timestamps</li><li><strong>PDF import progress</strong> - Each page extraction logged</li><li><strong>OCR processing</strong> - Per-image processing logged</li><li><strong>DOCX export</strong> - Export operations tracked</li></ul><h3 id="_6-👁️-full-transparency" tabindex="-1">6. 👁️ <strong>Full Transparency</strong> <a class="header-anchor" href="#_6-👁️-full-transparency" aria-label="Permalink to &quot;6. 👁️ **Full Transparency**&quot;">​</a></h3><ul><li><strong>&quot;Show Prompt&quot; button</strong> - View exact instructions sent to AI</li><li><strong>Configuration display</strong> - See model, formatting settings, max tokens</li><li><strong>No black boxes</strong> - Complete visibility into AI processing</li></ul><h3 id="_7-📊-professional-session-reports" tabindex="-1">7. 📊 <strong>Professional Session Reports</strong> <a class="header-anchor" href="#_7-📊-professional-session-reports" aria-label="Permalink to &quot;7. 📊 **Professional Session Reports**&quot;">​</a></h3><ul><li><strong>Markdown format</strong> - Clean, readable documentation</li><li><strong>Complete configuration</strong> - All settings recorded</li><li><strong>Processing summary</strong> - Table of all images and status</li><li><strong>Full extracted text</strong> - All OCR results included</li><li><strong>Statistics</strong> - Character/word counts and averages</li><li><strong>Supervertaler branding</strong> - Professional client-ready reports</li></ul><h3 id="_8-💾-flexible-export-options" tabindex="-1">8. 💾 <strong>Flexible Export Options</strong> <a class="header-anchor" href="#_8-💾-flexible-export-options" aria-label="Permalink to &quot;8. 💾 **Flexible Export Options**&quot;">​</a></h3><ul><li><strong>DOCX export</strong> - Formatted Word documents with optional bold/italic/underline</li><li><strong>Copy to clipboard</strong> - Quick text extraction</li><li><strong>Session reports</strong> - Professional MD documentation</li></ul><h3 id="_9-🚀-standalone-mode" tabindex="-1">9. 🚀 <strong>Standalone Mode</strong> <a class="header-anchor" href="#_9-🚀-standalone-mode" aria-label="Permalink to &quot;9. 🚀 **Standalone Mode**&quot;">​</a></h3><p>Can run independently outside Supervertaler:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modules/pdf_rescue.py</span></span></code></pre></div><p>Full-featured standalone application with all capabilities.</p><hr><h2 id="🎯-workflow" tabindex="-1">🎯 Workflow <a class="header-anchor" href="#🎯-workflow" aria-label="Permalink to &quot;🎯 Workflow&quot;">​</a></h2><h3 id="quick-start-5-steps" tabindex="-1">Quick Start (5 Steps) <a class="header-anchor" href="#quick-start-5-steps" aria-label="Permalink to &quot;Quick Start (5 Steps)&quot;">​</a></h3><ol><li><strong>Open PDF Rescue</strong> - Navigate to Assistant panel → PDF Rescue tab</li><li><strong>Import PDF</strong> - Click &quot;📄 PDF&quot; button, select your badly-formatted PDF</li><li><strong>Check formatting option</strong> - Leave &quot;Preserve formatting&quot; checked (default)</li><li><strong>Process</strong> - Click &quot;⚡ Process ALL&quot; to OCR all pages</li><li><strong>Export</strong> - Click &quot;💾 Save DOCX&quot; to create Word document</li></ol><p><strong>That&#39;s it!</strong> You now have a clean, editable Word document ready for translation.</p><hr><h3 id="detailed-workflow" tabindex="-1">Detailed Workflow <a class="header-anchor" href="#detailed-workflow" aria-label="Permalink to &quot;Detailed Workflow&quot;">​</a></h3><h4 id="step-1-import-your-pdf" tabindex="-1">Step 1: Import Your PDF <a class="header-anchor" href="#step-1-import-your-pdf" aria-label="Permalink to &quot;Step 1: Import Your PDF&quot;">​</a></h4><p><strong>Method 1: Direct PDF Import</strong> (Recommended)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Click: 📄 PDF button</span></span>
<span class="line"><span>→ Select PDF file</span></span>
<span class="line"><span>→ Automatic page extraction to {filename}_images/ folder</span></span>
<span class="line"><span>→ All pages added to processing queue</span></span></code></pre></div><p><strong>Method 2: Manual Image Import</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Click: 📁 Add Files → Select individual images</span></span>
<span class="line"><span>OR</span></span>
<span class="line"><span>Click: 📂 Folder → Select folder with images</span></span></code></pre></div><p><strong>Result</strong>: All images listed in left panel with ✓ status indicators</p><hr><h4 id="step-2-configure-settings" tabindex="-1">Step 2: Configure Settings <a class="header-anchor" href="#step-2-configure-settings" aria-label="Permalink to &quot;Step 2: Configure Settings&quot;">​</a></h4><p><strong>Model Selection</strong>:</p><ul><li><code>gpt-4o</code> (Recommended) - Latest, fastest, best quality</li><li><code>gpt-4o-mini</code> - Budget option, good quality</li><li><code>gpt-4-turbo</code> - Alternative, similar quality to gpt-4o</li></ul><p><strong>Formatting Option</strong>:</p><ul><li>✓ <strong>Preserve formatting (bold/italic/underline)</strong> - Enabled by default</li><li>Unchecked = Plain text output only</li></ul><p><strong>Extraction Instructions</strong>:</p><ul><li>Default instructions optimized for badly formatted PDFs</li><li>Handles redactions, stamps, signatures automatically</li><li>Can customize if needed (advanced)</li><li>Click <strong>&quot;👁️ Show Prompt&quot;</strong> to see exact AI instructions</li></ul><hr><h4 id="step-3-process-images" tabindex="-1">Step 3: Process Images <a class="header-anchor" href="#step-3-process-images" aria-label="Permalink to &quot;Step 3: Process Images&quot;">​</a></h4><p><strong>Option A: Process Selected</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Select image(s) in list</span></span>
<span class="line"><span>2. Click: 🔍 Process Selected</span></span>
<span class="line"><span>3. View result in preview pane</span></span></code></pre></div><p><strong>Option B: Process All</strong> (Recommended)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Click: ⚡ Process ALL</span></span>
<span class="line"><span>2. Confirm batch processing dialog</span></span>
<span class="line"><span>3. Watch progress bar</span></span>
<span class="line"><span>4. All pages processed automatically</span></span></code></pre></div><p><strong>Processing Details</strong>:</p><ul><li>Each image sent to the OCR model</li><li>Text extracted with context awareness</li><li>Formatting detected (if enabled)</li><li>Redactions/stamps/signatures handled</li><li>Results stored in memory</li><li>✓ indicator appears when processed</li></ul><hr><h4 id="step-4-review-export" tabindex="-1">Step 4: Review &amp; Export <a class="header-anchor" href="#step-4-review-export" aria-label="Permalink to &quot;Step 4: Review &amp; Export&quot;">​</a></h4><p><strong>Review Extracted Text</strong>:</p><ul><li>Click any processed image in list</li><li>Preview pane shows extracted text</li><li>Formatting shown as markdown (<code>**bold**</code>, <code>*italic*</code>, etc.)</li><li>Verify quality before export</li></ul><p><strong>Export Options</strong>:</p><ol><li><p><strong>💾 Save DOCX</strong> (Primary export)</p><ul><li>Formatted Word document</li><li>Markdown converted to proper formatting</li><li>One page per document page</li><li>Page headers with filenames</li><li>Ready for translation work</li></ul></li><li><p><strong>📋 Copy All</strong></p><ul><li>All text to clipboard</li><li>Includes page separators</li><li>Quick paste into any application</li></ul></li><li><p><strong>📊 Session Report</strong></p><ul><li>Professional markdown documentation</li><li>Complete configuration record</li><li>All extracted text included</li><li>Statistics and metadata</li><li>Client-ready deliverable</li></ul></li></ol>`,72)]))}const h=t(i,[["render",r]]);export{u as __pageData,h as default};
